package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC4", "AES-128", "Blowfish", "SHA-1", "RSA-1024", "DSA-1024"}
insufficient_key_lengths := {"1024", "128", "512"}
outdated_protocols := {"TLS 1.0", "TLS 1.1", "SSLv3", "SSLv2", "TLS_1_0", "TLS_1_1"}
weak_cipher_suites := {"CBC", "DES", "RC4", "EXPORT", "NULL", "DES-CBC3-SHA", "RC4-SHA"}
static_key_indicators := {"false", "disabled", "0"}
rotation_keywords := {"rotation", "key_lifetime", "static_key"}
algorithm_keywords := {"algorithm", "cipher", "encryption_type"}
key_length_keywords := {"key_size", "bit_length", "key_length", "modulus_length"}
protocol_keywords := {"protocol", "ssl_policy", "tls_version", "min_protocol_version"}
cipher_suite_keywords := {"ciphers", "cipher_suites", "ssl_ciphers"}

check_weak_algorithm(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    some alg
    lower_alg := lower(alg)
    alg in weak_algorithms
    regex.match(sprintf("(?i).*%s.*", [lower_alg]), lower_value)
}

check_insufficient_key_length(value) {
    value.ir_type == "String"
    value.value in insufficient_key_lengths
} else {
    value.ir_type == "Integer"
    some length
    length in {1024, 128, 512}
    value.value == length
}

check_outdated_protocol(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    some protocol
    lower_protocol := lower(protocol)
    protocol in outdated_protocols
    regex.match(sprintf("(?i).*%s.*", [lower_protocol]), lower_value)
}

check_weak_cipher_suite(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    some cipher
    lower_cipher := lower(cipher)
    cipher in weak_cipher_suites
    regex.match(sprintf("(?i).*%s.*", [lower_cipher]), lower_value)
}

check_static_key(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    some indicator
    lower_indicator := lower(indicator)
    indicator in static_key_indicators
    regex.match(sprintf("(?i).*%s.*", [lower_indicator]), lower_value)
} else {
    value.ir_type == "Boolean"
    value.value == false
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attributes := glitch_lib.all_attributes(parent)
    attr := attributes[_]
    attr.name in algorithm_keywords
    check_weak_algorithm(attr.value)
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Weak encryption algorithm detected - Using inadequate cryptographic algorithms may lead to data exposure. (CWE-326)"
    }
}

