contains_weak_algorithm(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    some alg
    weak_algorithms[alg]
    lower_alg := lower(alg)
    regex.match(sprintf("(?i).*%s.*", [lower_alg]), lower_value)
} else {
    value.ir_type == "FunctionCall"
    some arg
    arg in value.args
    arg.ir_type == "String"
    lower_arg := lower(arg.value)
    some alg
    weak_algorithms[alg]
    lower_alg := lower(alg)
    regex.match(sprintf("(?i).*%s.*", [lower_alg]), lower_arg)
}

